import java.util.*;
import java.math.BigInteger;
import java.util.function.*;

public class Main {
    static final int MOD = 998244353;
    static final long MOD7 = 1000000007L;
    static long[] pw10 = new long[17];

    static BigInteger solve(int[] variables, int base) {
        List<Integer> rem1 = new ArrayList<>();
        int[] curArr = new int[]{base};
        int until = variables.length / 2;
        bruteRec(0, until, curArr, variables, rem1);
        List<Integer> rem2 = new ArrayList<>(rem1);
        rem1.clear();
        curArr[0] = 0;
        until = variables.length;
        bruteRec(variables.length / 2, until, curArr, variables, rem1);

        Collections.sort(rem1);
        Collections.sort(rem2);

        long totalrsum = 0;
        for (int x : rem2) totalrsum += x;
        int j = rem2.size() - 1;
        BigInteger add = BigInteger.ZERO;
        for (int a : rem1) {
            while (j >= 0 && a + rem2.get(j) >= MOD) --j;
            long term = a * (long)rem2.size() + totalrsum - (rem2.size() - 1 - j) * (long)MOD;
            add = add.add(BigInteger.valueOf(term));
        }
        return add;
    }

    static void bruteRec(int pos, int until, int[] curArr, int[] variables, List<Integer> rem1) {
        if (pos == until) {
            rem1.add(curArr[0]);
            return;
        }
        int oldcur = curArr[0];
        for (int t = 0; t < 10; ++t) {
            bruteRec(pos + 1, until, curArr, variables, rem1);
            curArr[0] = (curArr[0] + variables[pos]) % MOD;
        }
        curArr[0] = oldcur;
    }

    static long count_with_prefix(String s, long n, String n_str) {
        long ans = 0;
        long s_val = 0;
        for (char ch : s.toCharArray()) s_val = 10 * s_val + (ch - '0');
        for (int len = s.length(); len <= n_str.length(); ++len) {
            if (len < n_str.length()) {
                ans += pw10[len - s.length()];
            } else {
                int cmp = s.compareTo(n_str.substring(0, s.length()));
                if (cmp < 0) {
                    ans += pw10[len - s.length()];
                } else if (cmp == 0) {
                    ans += (n + 1) - s_val * pw10[n_str.length() - s.length()];
                }
            }
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        String n_str = Long.toString(n);

        pw10[0] = 1;
        for (int i = 1; i < 17; ++i)
            pw10[i] = 10 * pw10[i - 1];

        BigInteger ans = BigInteger.ZERO;

        for (int len = 1; len <= n_str.length(); ++len) {
            long cur = 0;
            StringBuilder curst = new StringBuilder();

            for (int firstdiff = 0; firstdiff < n_str.length() && firstdiff < len; ++firstdiff) {
                if (firstdiff > 0) {
                    cur = 10 * cur + (n_str.charAt(firstdiff - 1) - '0');
                    curst.append(n_str.charAt(firstdiff - 1));
                }

                for (int lastdig = 0; lastdig <= 9; ++lastdig) {
                    if (firstdiff == 0 && lastdig == 0) continue;
                    if (lastdig == n_str.charAt(firstdiff) - '0') continue;
                    if (len == n_str.length() && lastdig > n_str.charAt(firstdiff) - '0') continue;

                    long curp = 10 * cur + lastdig;
                    String curstp = curst.toString() + (char)('0' + lastdig);

                    long base = 0;
                    StringBuilder tmp = new StringBuilder();
                    for (int pos = 0; pos < curstp.length(); ++pos) {
                        char start = (pos == 0 ? '1' : '0');
                        for (char dig = start; dig < curstp.charAt(pos); ++dig) {
                            base += count_with_prefix(tmp.toString() + dig, n, n_str);
                        }
                        tmp.append(curstp.charAt(pos));
                    }
                    base += len - 1;
                    base += 1;
                    base -= curp * pw10[len - curstp.length()];
                    base %= MOD;
                    if (base < 0) base += MOD;

                    int varLen = len - curstp.length();
                    int[] variables = new int[varLen];
                    tmp = new StringBuilder();
                    for (int pos = curstp.length(); pos < len; ++pos) {
                        variables[pos - curstp.length()] = (int)(count_with_prefix(tmp.toString() + '0', n, n_str) % MOD);
                        tmp.append('0');
                    }
                    for (int t = 0; t < varLen; ++t) {
                        variables[varLen - 1 - t] -= (int)(pw10[t] % MOD);
                    }
                    for (int i = 0; i < varLen; ++i) {
                        variables[i] %= MOD;
                        if (variables[i] < 0) variables[i] += MOD;
                    }

                    ans = ans.add(solve(variables, (int)base));
                }
            }
        }

        long cur = 0;
        StringBuilder curst = new StringBuilder();
        for (int len = 1; len <= n_str.length(); ++len) {
            curst.append(n_str.charAt(len - 1));
            cur = 10 * cur + (n_str.charAt(len - 1) - '0');

            long val = 1;
            StringBuilder tmp = new StringBuilder();
            for (int pos = 0; pos < curst.length(); ++pos) {
                char start = (pos == 0 ? '1' : '0');
                for (char dig = start; dig < curst.charAt(pos); ++dig) {
                    val += count_with_prefix(tmp.toString() + dig, n, n_str);
                }
                tmp.append(curst.charAt(pos));
            }
            val += len - 1;
            val -= cur;
            val %= MOD;
            if (val < 0) val += MOD;
            ans = ans.add(BigInteger.valueOf(val));
        }

        ans = ans.mod(BigInteger.valueOf(MOD7));
        System.out.println(ans.toString());
    }
}
